package david.manager;
import java.io.*;import java.util.*;import java.util.zip.*;import java.nio.charset.StandardCharsets;import java.security.*;import java.security.cert.*;import com.android.apksig.*;
public class ApkSmokeTest {
 public static void main(String[] a)throws Exception{
  File src=new File(a[0]),out=new File(a[1]),keyfile=new File(a[2]);byte[] manifest=FileOps.zipEntry(src,"AndroidManifest.xml",1000000);Axml codec=new Axml();String xml=codec.decode(manifest);if(!xml.contains("david.manager"))throw new AssertionError("Package missing");byte[] patched=codec.encode(xml.replace("Cyber Hub Manager","Cyber Hub Manager Test"));FileOps.rewriteZip(src,out,Collections.singletonMap("AndroidManifest.xml",patched));
  if(!new Axml().decode(FileOps.zipEntry(out,"AndroidManifest.xml",1000000)).contains("Cyber Hub Manager Test"))throw new AssertionError("Edit missing");
  File signed=new File(out.getParentFile(),"roundtrip-signed.apk");KeyStore ks=KeyStore.getInstance("PKCS12");char[] pass="cyberhub-development".toCharArray();try(InputStream in=new FileInputStream(keyfile)){ks.load(in,pass);}String alias=ks.aliases().nextElement();ApkSigner.SignerConfig sc=new ApkSigner.SignerConfig.Builder("test",(PrivateKey)ks.getKey(alias,pass),Collections.singletonList((X509Certificate)ks.getCertificate(alias))).build();new ApkSigner.Builder(Collections.singletonList(sc)).setInputApk(out).setOutputApk(signed).setMinSdkVersion(26).setV1SigningEnabled(true).setV2SigningEnabled(true).setV3SigningEnabled(true).build().sign();ApkVerifier.Result result=new ApkVerifier.Builder(signed).build().verify();if(!result.isVerified())throw new AssertionError(result.getErrors());System.out.println("PASS APK manifest edit + rebuild + signing + verify");
  File alignment=new File(out.getParentFile(),"stored.apk");try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(alignment))){for(String n:new String[]{"resources.arsc","lib/arm64-v8a/libfixture.so"}){byte[] b=new byte[50];CRC32 crc=new CRC32();crc.update(b);ZipEntry e=new ZipEntry(n);e.setMethod(0);e.setSize(b.length);e.setCompressedSize(b.length);e.setCrc(crc.getValue());z.putNextEntry(e);z.write(b);z.closeEntry();}}
  File aligned=new File(out.getParentFile(),"stored-aligned.apk");FileOps.rewriteZip(alignment,aligned,Collections.emptyMap());byte[] raw=FileOps.read(aligned,1000000);try(ZipFile z=new ZipFile(aligned)){Enumeration<? extends ZipEntry>en=z.entries();int p=0;while(en.hasMoreElements()){ZipEntry e=en.nextElement();int name=(raw[p+26]&255)|(raw[p+27]&255)<<8,extra=(raw[p+28]&255)|(raw[p+29]&255)<<8;int start=p+30+name+extra;int align=e.getName().endsWith(".so")?16384:4;if(start%align!=0)throw new AssertionError("Not aligned "+e.getName()+" "+start);p=start+(int)e.getCompressedSize();}}System.out.println("PASS stored resources alignment and 16 KB native library alignment");
 }
}